#include "exotic/autonomy/agents/in_memory_repository.hpp"
#include "exotic/autonomy/agents/recovery.hpp"
#include <cassert>
using namespace exotic::autonomy;using namespace exotic::autonomy::agents;
int main(){InMemoryAgentRepository repo;AgentRegistry registry{repo};CapabilityDefinition d;d.key="worker";d.name="Worker";registry.define_capability(d);auto make=[&](std::string key,TimePoint heartbeat){AgentIdentity a;a.identity_key=key;a.display_name=key;a.health=HealthState::Healthy;a.trust=TrustLevel::Elevated;a.workload.maximum_tasks=1;auto id=registry.register_agent(a);registry.activate(id);WorkloadState w;w.maximum_tasks=1;registry.heartbeat(id,HealthState::Healthy,Availability::Available,w,heartbeat);registry.grant_capability({id,"worker",0.9,0.9,0,0,Clock::now()});return id;};const auto now=Clock::now();auto stale=make("stale",now);auto replacement=make("replacement",now);AllowAllGovernanceCompatibility gov;AllowAllResourceCompatibility res;CandidateScorer scorer{repo,registry,gov,res};WorkAllocator allocator{repo,scorer};TaskRequirement req;req.job_id=4;req.proposal_id=4;req.capabilities={{"worker",0.8,0.8,true,1.0}};req.excluded_agents={replacement};auto allocation=allocator.allocate(req);assert(allocation.allocated&&allocation.assignment);assert(allocation.assignment->plan.agent_ids.front()==stale);WorkloadState stale_workload;stale_workload.maximum_tasks=1;registry.heartbeat(stale,HealthState::Healthy,Availability::Available,stale_workload,now-std::chrono::minutes(2));auto assignment=*allocation.assignment;assignment.status=AssignmentStatus::Running;repo.save_assignment(assignment);WorkerBinding binding;binding.id=repo.next_worker_binding_id();binding.assignment_id=assignment.id;binding.job_id=assignment.job_id;binding.agent_id=stale;binding.worker_key="stale";binding.expires_at=now-std::chrono::seconds(1);repo.save_worker_binding(binding);assignment.requirement.excluded_agents.clear();repo.save_assignment(assignment);AgentRecoveryManager recovery{repo,allocator};auto report=recovery.recover(now,std::chrono::seconds(30));assert(report.stale_agents==1);assert(report.released_bindings==1);auto recovered=repo.load_assignment(assignment.id);assert(recovered);assert(recovered->continuity_key==assignment.continuity_key);assert(recovered->plan.agent_ids.front()==replacement||recovered->status==AssignmentStatus::Interrupted);return 0;}
